#include <iostream>
#include <vector>
#include <algorithm>
#include <cstring>
#include <queue>
using namespace std;

const int MAXN = 202;
const int INF = 0x3f3f3f3f;

int flow[MAXN][MAXN];
int cap[MAXN][MAXN];
int pre[MAXN], que[MAXN], dist[MAXN];

int maxFlow(int n, int s, int t) {
    int totalFlow = 0;
    while (true) {
        memset(pre, -1, sizeof(pre));
        dist[s] = INF;
        int front = 0, rear = 0;
        que[rear++] = s;
        while (front < rear && pre[t] < 0) {
            int u = que[front++];
            for (int v = 0; v < n; v++) {
                if (pre[v] < 0 && cap[u][v] - flow[u][v] > 0) {
                    pre[v] = u;
                    dist[v] = min(dist[u], cap[u][v] - flow[u][v]);
                    que[rear++] = v;
                }
            }
        }
        if (pre[t] < 0) break;
        for (int v = t; v != s; v = pre[v]) {
            flow[pre[v]][v] += dist[t];
            flow[v][pre[v]] -= dist[t];
        }
        totalFlow += dist[t];
    }
    return totalFlow;
}

char gridA[11][11], gridB[11][11];
int bi, bj, directions[][2] = {{0,1},{0,-1},{1,0},{-1,0}};
int matrix[101][101];
int size, timeLimit;
vector<int> listA, listB, listC;

void explore(int A, int B, int* visited, bool check) {
    queue<pair<int,int>> q;
    visited[A*size+B] = 0;
    q.push({A, B});
    while (!q.empty()) {
        auto current = q.front(); q.pop();
        int p = current.first * size + current.second;
        int dis = visited[p];
        if (check && (matrix[bi*size+bj][p] <= dis || timeLimit <= dis)) {
            if (matrix[bi*size+bj][p] < dis || timeLimit < dis) visited[p] = INF+1;
            continue;
        }
        for (int d=0; d<4; d++) {
            int ni = current.first + directions[d][0];
            int nj = current.second + directions[d][1];
            if (ni<0 || nj<0 || ni>=size || nj>=size) continue;
            if (gridB[ni][nj]<'0' || gridB[ni][nj]>'9') continue;
            int qIdx = ni*size+nj;
            if (visited[qIdx]!=INF) continue;
            visited[qIdx] = dis+1;
            q.push({ni, nj});
        }
    }
}

void setup() {
    for (int i=0; i<size; ++i) {
        for (int j=0; j<size; ++j) {
            if (gridB[i][j]<'0' || gridB[i][j]>'9') continue;
            listA.push_back(i);
            listB.push_back(j);
            int p = i*size + j;
            cap[p+2+size*size][1] = gridB[i][j]-'0';
        }
    }
    int z = bi*size + bj;
    for (int i=0; i<size; ++i) {
        for (int j=0; j<size; ++j) {
            if (gridA[i][j]<'0' || gridA[i][j]>'9') continue;
            int p = i*size + j;
            cap[0][p+2] = gridA[i][j]-'0';
            for (int k=0; k<(int)listA.size(); ++k) {
                int ii = listA[k], jj = listB[k], qIdx=ii*size+jj;
                if (matrix[p][qIdx]<INF)
                    cap[p+2][qIdx+2+size*size]=INF;
            }
        }
    }
}

int main() {
    int n, t;
    cin >> n >> t;
    size = n;
    memset(matrix, 0x3f, sizeof(matrix));
    for (int i=0; i<n; ++i) cin >> gridA[i];
    for (int i=0; i<n; ++i) cin >> gridB[i];
    for (int i=0; i<n; ++i)
        for (int j=0; j<n; ++j)
            if (gridA[i][j]=='Z') bi=i, bj=j;
    explore(bi, bj, matrix[bi*size+bj], false);
    for (int i=0; i<n; ++i)
        for (int j=0; j<n; ++j)
            if (gridA[i][j]>='1' && gridA[i][j]<='9')
                explore(i, j, matrix[i*size+j], true);
    setup();
    cout << maxFlow(2+size*size, 0, 1) << "\n";
}
